   134→	if err != nil {
   135→		return nil, err
   136→	}
   137→	var attr payloadattribute.Attributer
   138→	switch st.Version() {
   139→	case version.Deneb, version.Electra, version.Fulu:
   140→		withdrawals, _, err := st.ExpectedWithdrawals()
   141→		if err != nil {
   142→			return nil, err
   143→		}
   144→		attr, err = payloadattribute.New(&enginev1.PayloadAttributesV3{
   145→			Timestamp:             uint64(t.Unix()),
   146→			PrevRandao:            random,
   147→			SuggestedFeeRecipient: val.FeeRecipient[:],
   148→			Withdrawals:           withdrawals,
   149→			ParentBeaconBlockRoot: parentRoot[:],
   150→		})
   151→		if err != nil {
   152→			return nil, err
   153→		}
   154→	case version.Capella:
   155→		withdrawals, _, err := st.ExpectedWithdrawals()
   156→		if err != nil {
   157→			return nil, err
   158→		}
   159→		attr, err = payloadattribute.New(&enginev1.PayloadAttributesV2{
   160→			Timestamp:             uint64(t.Unix()),
   161→			PrevRandao:            random,
   162→			SuggestedFeeRecipient: val.FeeRecipient[:],
   163→			Withdrawals:           withdrawals,
   164→		})
   165→		if err != nil {
   166→			return nil, err
   167→		}
   168→	case version.Bellatrix:
   169→		attr, err = payloadattribute.New(&enginev1.PayloadAttributes{
   170→			Timestamp:             uint64(t.Unix()),
   171→			PrevRandao:            random,
   172→			SuggestedFeeRecipient: val.FeeRecipient[:],
   173→		})
   174→		if err != nil {
   175→			return nil, err
   176→		}
   177→	default:
   178→		return nil, errors.New("unknown beacon state version")
   179→	}
   180→	payloadID, _, err := vs.ExecutionEngineCaller.ForkchoiceUpdated(ctx, f, attr)
   181→	if err != nil {
   182→		return nil, errors.Wrap(err, "could not prepare payload")
   183→	}
   184→	if payloadID == nil {
   185→		return nil, fmt.Errorf("nil payload with block hash: %#x", parentHash)
   186→	}
   187→	res, err := vs.ExecutionEngineCaller.GetPayload(ctx, *payloadID, slot)
   188→	if err != nil {
   189→		return nil, err
   190→	}
   191→
   192→	warnIfFeeRecipientDiffers(val.FeeRecipient[:], res.ExecutionData.FeeRecipient())
   193→	log.WithField("value", res.Bid).Debug("Received execution payload from local engine")
   194→	return res, nil
   195→}
