   197→// warnIfFeeRecipientDiffers logs a warning if the fee recipient in the payload (eg the EL engine get payload response) does not
   198→// match what was expected (eg the fee recipient previously used to request preparation of the payload).
   199→func warnIfFeeRecipientDiffers(want, got []byte) {
   200→	if !bytes.Equal(want, got) {
   201→		logrus.WithFields(logrus.Fields{
   202→			"wantedFeeRecipient": fmt.Sprintf("%#x", want),
   203→			"received":           fmt.Sprintf("%#x", got),
   204→		}).Warn("Fee recipient address from execution client is not what was expected. " +
   205→			"It is possible someone has compromised your client to try and take your transaction fees")
   206→	}
   207→}
   208→
   209→// This returns the valid terminal block hash with an existence bool value.
   210→//
   211→// Spec code:
   212→// def get_terminal_pow_block(pow_chain: Dict[Hash32, PowBlock]) -> Optional[PowBlock]:
   213→//
