   215→//	    # Terminal block hash override takes precedence over terminal total difficulty
   216→//	    if TERMINAL_BLOCK_HASH in pow_chain:
   217→//	        return pow_chain[TERMINAL_BLOCK_HASH]
   218→//	    else:
   219→//	        return None
   220→//
   221→//	return get_pow_block_at_terminal_total_difficulty(pow_chain)
   222→func (vs *Server) getTerminalBlockHashIfExists(ctx context.Context, transitionTime uint64) ([]byte, bool, error) {
   223→	terminalBlockHash := params.BeaconConfig().TerminalBlockHash
   224→	// Terminal block hash override takes precedence over terminal total difficulty.
   225→	if params.BeaconConfig().TerminalBlockHash != params.BeaconConfig().ZeroHash {
   226→		exists, _, err := vs.Eth1BlockFetcher.BlockExists(ctx, terminalBlockHash)
   227→		if err != nil {
   228→			return nil, false, err
   229→		}
   230→		if !exists {
   231→			return nil, false, nil
   232→		}
   233→
   234→		return terminalBlockHash.Bytes(), true, nil
   235→	}
   236→
   237→	return vs.ExecutionEngineCaller.GetTerminalBlockHash(ctx, transitionTime)
   238→}
   239→
   240→func (vs *Server) getBuilderPayloadAndBlobs(ctx context.Context,
   241→	slot primitives.Slot,
   242→	vIdx primitives.ValidatorIndex,
   243→	parentGasLimit uint64) (builder.Bid, error) {
   244→	ctx, span := trace.StartSpan(ctx, "ProposerServer.getBuilderPayloadAndBlobs")
   245→	defer span.End()
   246→
   247→	if slots.ToEpoch(slot) < params.BeaconConfig().BellatrixForkEpoch {
   248→		return nil, nil
   249→	}
   250→	canUseBuilder, err := vs.canUseBuilder(ctx, slot, vIdx)
   251→	if err != nil {
   252→		return nil, errors.Wrap(err, "failed to check if we can use the builder")
   253→	}
   254→	span.SetAttributes(trace.BoolAttribute("canUseBuilder", canUseBuilder))
   255→	if !canUseBuilder {
   256→		return nil, nil
   257→	}
   258→
   259→	return vs.getPayloadHeaderFromBuilder(ctx, slot, vIdx, parentGasLimit)
   260→}
   261→
   262→var errActivationNotReached = errors.New("activation epoch not reached")
   263→var errNoTerminalBlockHash = errors.New("no terminal block hash")
   264→
   265→// getParentBlockHash retrieves the parent block hash of the block at the given slot.
   266→// The function's behavior varies depending on the state version and whether the merge has been completed.
   267→//
   268→// For states of version Capella or later, the block hash is directly retrieved from the state's latest execution payload header.
   269→//
   270→// If the merge transition has been completed, the parent block hash is also retrieved from the state's latest execution payload header.
   271→//
   272→// If the activation epoch has not been reached, an errActivationNotReached error is returned.
   273→//
   274→// Otherwise, the terminal block hash is fetched based on the slot's time, and an error is returned if it doesn't exist.
   275→func (vs *Server) getParentBlockHash(ctx context.Context, st state.BeaconState, slot primitives.Slot) ([]byte, error) {
   276→	if st.Version() >= version.Capella {
   277→		return getParentBlockHashPostCapella(st)
   278→	}
   279→
   280→	mergeComplete, err := blocks.IsMergeTransitionComplete(st)
   281→	if err != nil {
