   288→	if activationEpochNotReached(slot) {
   289→		return nil, errActivationNotReached
   290→	}
   291→
   292→	return getParentBlockHashPreMerge(ctx, vs, st, slot)
   293→}
   294→
   295→// getParentBlockHashPostCapella retrieves the parent block hash for states of version Capella or later.
   296→func getParentBlockHashPostCapella(st state.BeaconState) ([]byte, error) {
   297→	header, err := st.LatestExecutionPayloadHeader()
   298→	if err != nil {
   299→		return nil, errors.Wrap(err, "could not get post capella payload header")
   300→	}
   301→	return header.BlockHash(), nil
