   303→
   304→// getParentBlockHashPostMerge retrieves the parent block hash after the merge has completed.
   305→func getParentBlockHashPostMerge(st state.BeaconState) ([]byte, error) {
   306→	header, err := st.LatestExecutionPayloadHeader()
   307→	if err != nil {
   308→		return nil, errors.Wrap(err, "could not get post merge payload header")
   309→	}
   310→	return header.BlockHash(), nil
   311→}
   312→
   313→// getParentBlockHashPreMerge retrieves the parent block hash before the merge has completed.
   314→func getParentBlockHashPreMerge(ctx context.Context, vs *Server, st state.BeaconState, slot primitives.Slot) ([]byte, error) {
   315→	t, err := slots.StartTime(st.GenesisTime(), slot)
   316→	if err != nil {
   317→		return nil, err
   318→	}
   319→
   320→	parentHash, hasTerminalBlock, err := vs.getTerminalBlockHashIfExists(ctx, uint64(t.Unix()))
   321→	if err != nil {
   322→		return nil, err
   323→	}
   324→	if !hasTerminalBlock {
   325→		return nil, errNoTerminalBlockHash
   326→	}
   327→	return parentHash, nil
   328→}
   329→
   330→// activationEpochNotReached returns true if activation epoch has not been reach.
   331→// Which satisfy the following conditions in spec:
   332→//
   333→//	  is_terminal_block_hash_set = TERMINAL_BLOCK_HASH != Hash32()
   334→//	  is_activation_epoch_reached = get_current_epoch(state) >= TERMINAL_BLOCK_HASH_ACTIVATION_EPOCH
   335→//	  if is_terminal_block_hash_set and not is_activation_epoch_reached:
   336→//		return True
   337→func activationEpochNotReached(slot primitives.Slot) bool {
   338→	terminalBlockHashSet := bytesutil.ToBytes32(params.BeaconConfig().TerminalBlockHash.Bytes()) != [32]byte{}
   339→	if terminalBlockHashSet {
   340→		return params.BeaconConfig().TerminalBlockHashActivationEpoch > slots.ToEpoch(slot)
   341→	}
   342→	return false
   343→}
