    51→const blockBuilderTimeout = 1 * time.Second
    52→const gasLimitAdjustmentFactor = 1024
    53→
    54→// Sets the execution data for the block. Execution data can come from local EL client or remote builder depends on validator registration and circuit breaker conditions.
    55→func setExecutionData(ctx context.Context, blk interfaces.SignedBeaconBlock, local *blocks.GetPayloadResponse, bid builder.Bid, builderBoostFactor primitives.Gwei) (primitives.Wei, enginev1.BlobsBundler, error) {
    56→	_, span := trace.StartSpan(ctx, "ProposerServer.setExecutionData")
    57→	defer span.End()
    58→
    59→	slot := blk.Block().Slot()
    60→	if slots.ToEpoch(slot) < params.BeaconConfig().BellatrixForkEpoch {
    61→		return primitives.ZeroWei(), nil, nil
    62→	}
    63→
    64→	if local == nil {
    65→		return primitives.ZeroWei(), nil, errors.New("local payload is nil")
    66→	}
    67→
    68→	// Use local payload if builder payload is nil.
    69→	if bid == nil {
    70→		return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
    71→	}
    72→
    73→	builderPayload, err := bid.Header()
    74→	if err != nil {
    75→		log.WithError(err).Warn("Proposer: failed to retrieve header from BuilderBid")
    76→		return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
    77→	}
    78→
    79→	switch {
    80→	case blk.Version() >= version.Capella:
    81→		withdrawalsMatched, err := matchingWithdrawalsRoot(local.ExecutionData, builderPayload)
    82→		if err != nil {
    83→			tracing.AnnotateError(span, err)
    84→			log.WithError(err).Warn("Proposer: failed to match withdrawals root")
    85→			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
    86→		}
    87→
    88→		// Compare payload values between local and builder. Default to the local value if it is higher.
    89→		localValueGwei := primitives.WeiToGwei(local.Bid)
    90→		builderValueGwei := primitives.WeiToGwei(bid.Value())
    91→		minBid := primitives.Gwei(params.BeaconConfig().MinBuilderBid)
    92→		// Use local block if min bid is not attained
    93→		if builderValueGwei < minBid {
    94→			log.WithFields(logrus.Fields{
    95→				"minBuilderBid":    minBid,
    96→				"builderGweiValue": builderValueGwei,
    97→			}).Warn("Proposer: using local execution payload because min bid not attained")
    98→			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
    99→		}
   100→
   101→		// Use local block if min difference is not attained
   102→		minDiff := localValueGwei + primitives.Gwei(params.BeaconConfig().MinBuilderDiff)
   103→		if builderValueGwei < minDiff {
   104→			log.WithFields(logrus.Fields{
   105→				"localGweiValue":   localValueGwei,
   106→				"minBidDiff":       minDiff,
   107→				"builderGweiValue": builderValueGwei,
   108→			}).Warn("Proposer: using local execution payload because min difference with local value was not attained")
   109→			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
   110→		}
   111→
   112→		// Use builder payload if the following in true:
   113→		// builder_bid_value * builderBoostFactor(default 100) > local_block_value * (local-block-value-boost + 100)
   114→		boost := primitives.Gwei(params.BeaconConfig().LocalBlockValueBoost)
   115→		higherValueBuilder := builderValueGwei*builderBoostFactor > localValueGwei*(100+boost)
   116→		if boost > 0 && builderBoostFactor != defaultBuilderBoostFactor {
   117→			log.WithFields(logrus.Fields{
   118→				"localGweiValue":       localValueGwei,
   119→				"localBoostPercentage": boost,
   120→				"builderGweiValue":     builderValueGwei,
   121→				"builderBoostFactor":   builderBoostFactor,
   122→			}).Warn("Proposer: both local boost and builder boost are using non default values")
   123→		}
   124→		builderValueGweiGauge.Set(float64(builderValueGwei))
   125→		localValueGweiGauge.Set(float64(localValueGwei))
   126→
   127→		// If we can't get the builder value, just use local block.
   128→		if higherValueBuilder && withdrawalsMatched { // Builder value is higher and withdrawals match.
   129→			var builderKzgCommitments [][]byte
   130→			if bid.Version() >= version.Deneb {
   131→				bidDeneb, ok := bid.(builder.BidDeneb)
   132→				if !ok {
   133→					log.Warnf("Bid type %T does not implement builder.BidDeneb", bid)
   134→					return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
   135→				} else {
   136→					builderKzgCommitments = bidDeneb.BlobKzgCommitments()
   137→				}
   138→			}
   139→
